#version 300
uniform shader image;
uniform float2 size;
uniform float2 layer;
uniform float3x3 fromLayer;
uniform float3x3 toLayer;
uniform float4 screen;
uniform float time;
float2 amzCoord;
float4 amzOutput;
float2 amzScreenNorm() { float2 p=amzCoord-screen.xy; return float2(p.x/screen.z,1.0-p.y/screen.w); }
float2 amzLayerNorm() { float3 p=toLayer*float3(amzCoord,1.0); float2 n=p.xy/p.z/layer; return float2(n.x,1.0-n.y); }
float2 amzLayerCenter() { float3 p=fromLayer*float3(layer*.5,1.0); return p.xy/p.z-screen.xy; }
float4x4 amzRowMatrix(float3x3 m) { return float4x4(m[0].x,m[1].x,0.0,m[2].x, m[0].y,m[1].y,0.0,m[2].y, 0.0,0.0,1.0,0.0, m[0].z,m[1].z,0.0,m[2].z); }
float4x4 amzLayerToScreen() {
    float3x3 toNorm=float3x3(1.0/screen.z,0.0,0.0, 0.0,-1.0/screen.w,0.0,-screen.x/screen.z,1.0+screen.y/screen.w,1.0);
    float3x3 toPixels=float3x3(layer.x,0.0,0.0, 0.0,-layer.y,0.0, 0.0,layer.y,1.0);
    return amzRowMatrix(toNorm*fromLayer*toPixels);
}
float4x4 amzScreenToLayer() {
    float3x3 toPixels=float3x3(screen.z,0.0,0.0, 0.0,-screen.w,0.0, screen.x,screen.y+screen.w,1.0);
    float3x3 toNorm=float3x3(1.0/layer.x,0.0,0.0, 0.0,-1.0/layer.y,0.0,0.0,1.0,1.0);
    return amzRowMatrix(toNorm*toLayer*toPixels);
}
float2 getTexSize(float2 v) { return v; }
int amzIntMax(int a,int b) { return int(max(float(a),float(b))); }
int amzIntMin(int a,int b) { return int(min(float(a),float(b))); }
int amzIntAbs(int a) { return int(abs(float(a))); }
int amzIntClamp(int a,int b,int c) { return int(clamp(float(a),float(b),float(c))); }
uniform float2 amzVelocity,amzPivot,amzScale;
uniform float amzAngularVelocity,amzScaleVelocity,amzStartTime,amzEndTime;

struct AC_ImageInfo { int texture; float2 amzLocal_size; };
const float3x3 labPlaneInverse=float3x3(1);
float4x4 amzQuaternion(float4 q) {
    q /= max(length(q),0.000001);
    float x=q.x,y=q.y,z=q.z,w=q.w;
    return float4x4(1-2*(y*y+z*z),2*(x*y+w*z),2*(x*z-w*y),0,
                    2*(x*y-w*z),1-2*(x*x+z*z),2*(y*z+w*x),0,
                    2*(x*z+w*y),2*(y*z-w*x),1-2*(x*x+y*y),0,0,0,0,1);
}
const int amzPass=0;
uniform float amzIteration;
float4 amzSample_inputImg(float2 uv) { return float4(image.eval(((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0))); }
float4 amzTexture(int tex,float2 uv) { if(tex==0) return amzSample_inputImg(uv);return float4(0.0); }
float4 amzTexture(int tex,float2 uv,float bias){return amzTexture(tex,uv);}
uniform float amzp_progress;
uniform float amzp_wipeMode;
uniform float amzp_angle;
uniform float amzp_edgeSoftness;
uniform float amzp_blobAmount;
uniform float amzp_blobScale;
uniform float amzp_shineAmount;
uniform float amzp_shineWidth;
uniform float amzp_lensStrength;
layout(color) uniform half4 amzp_shineColor;
uniform float amzp_invert;


         float hash(float2 p) {
            p = fract(p * float2(127.1, 311.7));
            p += dot(p, p + 19.19);
            return fract(p.x * p.y);
        }

         float noise(float2 p) {
            float2 i = floor(p);
            float2 f = fract(p);
            float2 u = f * f * (3.0 - 2.0 * f);
            return mix(
                mix(hash(i + float2(0.0,0.0)), hash(i + float2(1.0,0.0)), u.x),
                mix(hash(i + float2(0.0,1.0)), hash(i + float2(1.0,1.0)), u.x),
                u.y
            );
        }

         float fbm(float2 p) {
             float v = 0.0;
             float a = 0.5;
            float2x2 rot = float2x2(0.8660, 0.5, -0.5, 0.8660);
            for (int i = 0; i < 6; i++) {
                v += a * noise(p);
                p  = rot * p * 2.1;
                a *= 0.48;
            }
            return v;
        }

        void amzRender() {

            float2 uv = amzLayerNorm();
            int mode = int(floor(amzp_wipeMode + 0.5));
             float p_mapped = clamp((amzp_invert>0.5) ? (1.0 - amzp_progress) : amzp_progress, 0.0, 1.0);


            if (p_mapped <= 0.0) {
                amzOutput = amzTexture(0, amzScreenNorm());
                return;
            }

            if (p_mapped >= 1.0) {
                amzOutput = float4(0.0, 0.0, 0.0, 0.0);
                return;
            }


             float axis;
            if (mode == 0) {
                 float rad = amzp_angle * 3.14159265 / 180.0;
                axis = dot(uv - float2(0.5), float2(cos(rad), sin(rad))) * 0.7071 + 0.5;
            } else if (mode == 1) {
                axis = 1.0 - uv.x;
            } else if (mode == 2) {
                axis = uv.y;
            } else if (mode == 3) {
                axis = 1.0 - uv.y;
            } else if (mode == 4) {
                axis = 1.0 - clamp(length(uv - float2(0.5)) * 2.0, 0.0, 1.0);
            } else {
                float2 sc = uv * amzp_blobScale * 0.9;
                 float n1 = fbm(sc + float2(1.7, 3.4));
                 float n2 = fbm(sc + float2(n1 * 1.8, 5.1) + p_mapped * 0.3);
                axis = fbm(sc + float2(n2 * 1.5, n1 * 1.6) + p_mapped * 0.2);
            }
            axis = clamp(axis, 0.0, 1.0);


            float2 q  = uv * amzp_blobScale;
             float q1 = fbm(q);
             float q2 = fbm(q + float2(5.2, 1.3));
            float2 r  = uv * amzp_blobScale + float2(q1, q2) * 2.2;
             float r1 = fbm(r + float2(1.7, 9.2));
             float r2 = fbm(r + float2(8.3, 2.8));
             float blob = fbm(uv * amzp_blobScale + float2(r1, r2) * 2.0);
            blob = pow(clamp(blob, 0.0, 1.0), 0.45);

             float wipeVal = clamp(axis + (blob - 0.5) * amzp_blobAmount, 0.0, 1.0);

             float thresh = p_mapped;
             float d = wipeVal - thresh;


            float mask = smoothstep(-amzp_edgeSoftness, amzp_edgeSoftness, d);


             float lensZone = 1.0 - smoothstep(0.0, amzp_shineWidth * 5.0, abs(d));
             float rad2 = amzp_angle * 3.14159265 / 180.0;
            float2 lensDir  = normalize(float2(cos(rad2), sin(rad2)) + float2(0.001));
            float2 lensedUV = clamp(
                amzScreenNorm() + lensDir * lensZone * amzp_lensStrength * sign(d),
                float2(0.001), float2(0.999)
            );

            float4 texNormal = amzTexture(0, amzScreenNorm());
            float4 texLensed = amzTexture(0, lensedUV);
            float4 texColor  = mix(texNormal, texLensed,
                                 lensZone * min(amzp_lensStrength * 6.0, 1.0));


            float shine1 = smoothstep(0.0, amzp_shineWidth, d)
                         * (1.0 - smoothstep(amzp_shineWidth, amzp_shineWidth * 2.2, d));
            float shine2 = smoothstep(-amzp_shineWidth * 0.3, amzp_shineWidth * 1.5, d)
                         * (1.0 - smoothstep(amzp_shineWidth * 1.5, amzp_shineWidth * 4.0, d)) * 0.2;
            float shineFinal = clamp(shine1 + shine2, 0.0, 1.0) * amzp_shineAmount;





            float4 outColor = texColor * mask;


            outColor.rgb += amzp_shineColor.rgb * shineFinal * mask;
            outColor.a    = max(outColor.a, shineFinal * mask * 0.9);

            amzOutput = outColor;
        }


half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }

